<!--
 * 消息召回管理页面
 *
 * <p>消息/通知的撤回记录管理，支持按通知ID或消息ID执行召回操作。
 *
 * @path apps/message-web/src/views/recall/index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
import { $t } from '@ydsz/locales';
/**
 * 消息召回管理（操作入口页）
 * <p>消费后端契约 RecallController（src/api/recall.ts，auto-generated by bash/gen-contract.py）：
 * recallNotification() 召回通知，recallMessage() 按日志ID召回消息，
 * recallByMsgId() 按消息ID召回消息，recallBatch() 批量召回。
 * 两个 Tab 分别对应通知召回和消息召回操作。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import { Page } from '@ydsz/common-ui';

import { createLogger } from '@ydsz-core/shared/utils';
import {
  YdBadge,
  YdButton,
  YdCard,
  YdCardContent,
  YdInput,
  YdSelectBase,
  YdSelectContentBase,
  YdSelectItemBase,
  YdSelectTriggerBase,
  YdSelectValueBase,
  YdForm,
  YdFormItem,
  YdTabsContent,
  YdTabs,
  YdTimeline,
  YdTimelineItem,
} from '@ydsz-core/ydsz-ui';
import { onMounted, reactive, ref } from 'vue';

import { showToast } from '@ydsz/notification';
import { YdConfirm } from '@ydsz-core/popup-ui';

import { recallBatch, recallByMsgId, recallMessage, recallNotification } from '#/api/recall';
import type { RecallRequestDTO } from '#/api/models';

defineOptions({ name: 'RecallManagement' });

const logger = createLogger('recall-management');

/** 当前激活的 Tab */
const activeTab = ref('notification');

/** 通知召回表单 */
const notificationForm = reactive({
  userId: '',
  id: '',
  bizType: '',
  bizId: '',
  recallScope: 'SINGLE',
});

/** 消息召回表单 */
const messageForm = reactive({
  logId: '',
  msgId: '',
  id: '',
  bizType: '',
  bizId: '',
  recallScope: 'SINGLE',
});

/** 召回结果日志 */
const recallLogs = ref<RecallLogItem[]>([]);

/** 加载状态 */
const executing = ref(false);

/** 召回日志项 */
interface RecallLogItem {
  type: 'notification' | 'message';
  id: string;
  time: string;
  success: boolean;
  detail: string;
}

/** 执行通知召回 */
async function handleRecallNotification(): Promise<void> {
  if (!notificationForm.id.trim()) {
    showToast.warning($t('recall.notification.idRequired'));
    return;
  }
  try {
    await YdConfirm(
      $t('recall.notification.confirm', { id: notificationForm.id }),
      $t('recall.notification.confirmTitle'),
      { type: 'warning' },
    );
  } catch {
    logger.debug('用户取消通知召回操作');
    return;
  }
  executing.value = true;
  try {
    const success = await recallNotification(
      { userId: notificationForm.userId.trim() || undefined },
      {
        id: notificationForm.id.trim() || undefined,
        bizType: notificationForm.bizType.trim() || undefined,
        bizId: notificationForm.bizId.trim() || undefined,
        recallScope: notificationForm.recallScope,
      },
    );
    if (success) {
      showToast.success($t('recall.notification.success'));
      addRecallLog('notification', notificationForm.id, true, $t('recall.log.success'));
    } else {
      showToast.warning($t('recall.requestPending'));
      addRecallLog('notification', notificationForm.id, false, $t('recall.log.pending'));
    }
  } catch (error) {
    logger.warn('通知召回失败: {}', error);
    addRecallLog('notification', notificationForm.id, false, String(error));
  } finally {
    executing.value = false;
  }
}

/** 执行消息召回（按 logId） */
async function handleRecallByLogId(): Promise<void> {
  if (!messageForm.logId.trim()) {
    showToast.warning($t('recall.message.logIdRequired'));
    return;
  }
  try {
    await YdConfirm(
      $t('recall.message.confirmByLogId', { logId: messageForm.logId }),
      $t('recall.message.confirmTitle'),
      { type: 'warning' },
    );
  } catch {
    logger.debug('用户取消消息召回操作');
    return;
  }
  executing.value = true;
  try {
    const success = await recallMessage({ logId: messageForm.logId.trim() });
    if (success) {
      showToast.success($t('recall.message.success'));
      addRecallLog('message', messageForm.logId, true, $t('recall.log.byLogIdSuccess'));
    } else {
      showToast.warning($t('recall.requestPending'));
      addRecallLog('message', messageForm.logId, false, $t('recall.log.pending'));
    }
  } catch (error) {
    logger.warn('消息召回失败: {}', error);
    addRecallLog('message', messageForm.logId, false, String(error));
  } finally {
    executing.value = false;
  }
}

/** 执行消息召回（按 msgId） */
async function handleRecallByMsgId(): Promise<void> {
  if (!messageForm.msgId.trim()) {
    showToast.warning($t('recall.message.msgIdRequired'));
    return;
  }
  try {
    await YdConfirm(
      $t('recall.message.confirmByMsgId', { msgId: messageForm.msgId }),
      $t('recall.message.confirmTitle'),
      { type: 'warning' },
    );
  } catch {
    logger.debug('用户取消消息召回操作');
    return;
  }
  executing.value = true;
  try {
    const success = await recallByMsgId({ msgId: messageForm.msgId.trim() });
    if (success) {
      showToast.success($t('recall.message.success'));
      addRecallLog('message', messageForm.msgId, true, $t('recall.log.byMsgIdSuccess'));
    } else {
      showToast.warning($t('recall.requestPending'));
      addRecallLog('message', messageForm.msgId, false, $t('recall.log.pending'));
    }
  } catch (error) {
    logger.warn('消息召回失败: {}', error);
    addRecallLog('message', messageForm.msgId, false, String(error));
  } finally {
    executing.value = false;
  }
}

/** 批量召回 */
async function handleRecallBatch(): Promise<void> {
  const currentForm = activeTab.value === 'notification' ? notificationForm : messageForm;
  if (!currentForm.id.trim()) {
    showToast.warning($t('recall.batch.idRequired'));
    return;
  }
  try {
    await YdConfirm($t('recall.batch.confirm'), $t('recall.batch.confirmTitle'), {
      type: 'warning',
      confirmButtonText: $t('recall.batch.confirmButton'),
      cancelButtonText: $t('common.cancel'),
    });
  } catch {
    logger.debug('用户取消批量召回操作');
    return;
  }
  executing.value = true;
  try {
    const count = await recallBatch({
      id: currentForm.id.trim() || undefined,
      bizType: currentForm.bizType.trim() || undefined,
      bizId: currentForm.bizId.trim() || undefined,
      recallScope: 'BATCH',
    } as RecallRequestDTO);
    showToast.success($t('recall.batch.success', { count }));
    addRecallLog(
      activeTab.value as 'notification' | 'message',
      currentForm.id,
      true,
      $t('recall.log.batchSuccess', { count }),
    );
  } catch (error) {
    logger.warn('批量召回失败: {}', error);
    addRecallLog(
      activeTab.value as 'notification' | 'message',
      currentForm.id,
      false,
      String(error),
    );
  } finally {
    executing.value = false;
  }
}

/** 添加召回日志 */
function addRecallLog(
  type: 'notification' | 'message',
  id: string,
  success: boolean,
  detail: string,
): void {
  recallLogs.value.unshift({
    type,
    id,
    time: new Date().toLocaleTimeString(),
    success,
    detail,
  });
  // 最多保留 20 条记录
  if (recallLogs.value.length > 20) {
    recallLogs.value = recallLogs.value.slice(0, 20);
  }
}

/** 重置表单 */
function handleReset(): void {
  if (activeTab.value === 'notification') {
    notificationForm.userId = '';
    notificationForm.id = '';
    notificationForm.bizType = '';
    notificationForm.bizId = '';
    notificationForm.recallScope = 'SINGLE';
  } else {
    messageForm.logId = '';
    messageForm.msgId = '';
    messageForm.id = '';
    messageForm.bizType = '';
    messageForm.bizId = '';
    messageForm.recallScope = 'SINGLE';
  }
}

onMounted(() => {
  logger.info('消息召回管理页面已加载');
});
</script>

<template>
  <Page auto-content-height>
    <div class="recall-container p-5">
      <div class="grid grid-cols-1 gap-5 lg:grid-cols-3">
        <!-- 操作区 -->
        <div class="lg:col-span-2">
          <YdCard>
            <YdCardContent class="pt-4">
              <YdTabs v-model="activeTab">
                <!-- 通知召回 Tab -->
                <YdTabsContent :label="$t('recall.notification.tab')" name="notification">
                  <YdForm :model="notificationForm" label-width="100px" class="mt-4">
                    <YdFormItem :label="$t('recall.notification.userId')">
                      <YdInput
                        v-model="notificationForm.userId"
                        :placeholder="$t('recall.notification.userIdPlaceholder')"
                      />
                    </YdFormItem>
                    <YdFormItem :label="$t('recall.notification.id')" required>
                      <YdInput
                        v-model="notificationForm.id"
                        :placeholder="$t('recall.notification.idPlaceholder')"
                      />
                    </YdFormItem>
                    <YdFormItem :label="$t('recall.notification.bizType')">
                      <YdInput
                        v-model="notificationForm.bizType"
                        :placeholder="$t('recall.notification.bizTypePlaceholder')"
                      />
                    </YdFormItem>
                    <YdFormItem :label="$t('recall.notification.bizId')">
                      <YdInput
                        v-model="notificationForm.bizId"
                        :placeholder="$t('recall.notification.bizIdPlaceholder')"
                      />
                    </YdFormItem>
                    <YdFormItem :label="$t('recall.notification.scope')">
                      <YdSelectBase v-model="notificationForm.recallScope">
                        <YdSelectTriggerBase class="w-full">
                          <YdSelectValueBase />
                        </YdSelectTriggerBase>
                        <YdSelectContentBase>
                          <YdSelectItemBase value="SINGLE">
                            {{ $t('recall.scope.single') }}
                          </YdSelectItemBase>
                          <YdSelectItemBase value="BATCH">
                            {{ $t('recall.scope.batch') }}
                          </YdSelectItemBase>
                        </YdSelectContentBase>
                      </YdSelectBase>
                    </YdFormItem>
                    <YdFormItem>
                      <YdButton v-loading="executing" @click="handleRecallNotification">
                        {{ $t('recall.notification.execute') }}
                      </YdButton>
                      <YdButton variant="outline" @click="handleReset">
                        {{ $t('common.reset') }}
                      </YdButton>
                    </YdFormItem>
                  </YdForm>
                </YdTabsContent>

                <!-- 消息召回 Tab -->
                <YdTabsContent :label="$t('recall.message.tab')" name="message">
                  <YdForm :model="messageForm" label-width="100px" class="mt-4">
                    <YdFormItem :label="$t('recall.message.logId')">
                      <YdInput
                        v-model="messageForm.logId"
                        :placeholder="$t('recall.message.logIdPlaceholder')"
                      />
                    </YdFormItem>
                    <YdFormItem :label="$t('recall.message.msgId')">
                      <YdInput
                        v-model="messageForm.msgId"
                        :placeholder="$t('recall.message.msgIdPlaceholder')"
                      />
                    </YdFormItem>
                    <YdFormItem :label="$t('recall.message.batchId')">
                      <YdInput
                        v-model="messageForm.id"
                        :placeholder="$t('recall.message.batchIdPlaceholder')"
                      />
                    </YdFormItem>
                    <YdFormItem :label="$t('recall.message.bizType')">
                      <YdInput
                        v-model="messageForm.bizType"
                        :placeholder="$t('recall.message.bizTypePlaceholder')"
                      />
                    </YdFormItem>
                    <YdFormItem :label="$t('recall.message.bizId')">
                      <YdInput
                        v-model="messageForm.bizId"
                        :placeholder="$t('recall.message.bizIdPlaceholder')"
                      />
                    </YdFormItem>
                    <YdFormItem>
                      <div class="flex gap-2">
                        <YdButton v-loading="executing" @click="handleRecallByLogId">
                          {{ $t('recall.message.byLogId') }}
                        </YdButton>
                        <YdButton v-loading="executing" @click="handleRecallByMsgId">
                          {{ $t('recall.message.byMsgId') }}
                        </YdButton>
                        <YdButton
                          v-loading="executing"
                          variant="destructive"
                          @click="handleRecallBatch"
                        >
                          {{ $t('recall.batch.entry') }}
                        </YdButton>
                        <YdButton variant="outline" @click="handleReset">
                          {{ $t('common.reset') }}
                        </YdButton>
                      </div>
                    </YdFormItem>
                  </YdForm>
                </YdTabsContent>
              </YdTabs>
            </YdCardContent>
          </YdCard>
        </div>

        <!-- 操作日志区 -->
        <div>
          <YdCard>
            <YdCardContent class="pt-4">
              <h3 class="mb-3 text-base font-medium">{{ $t('recall.log.title') }}</h3>
              <YdTimeline v-if="recallLogs.length > 0">
                <YdTimelineItem
                  v-for="(log, index) in recallLogs"
                  :key="log.time ?? index"
                  :type="log.success ? 'success' : 'danger'"
                  :timestamp="log.time"
                >
                  <div class="text-sm">
                    <YdBadge :variant="log.type === 'notification' ? 'default' : 'outline'">
                      {{ log.type === 'notification' ? $t('recall.log.typeNotification') : $t('recall.log.typeMessage') }}
                    </YdBadge>
                    <span class="ml-2 font-mono">{{ log.id }}</span>
                  </div>
                  <p class="mt-1 text-xs text-gray-500">{{ log.detail }}</p>
                </YdTimelineItem>
              </YdTimeline>
              <div v-else class="py-8 text-center text-gray-400">
                {{ $t('recall.log.empty') }}
              </div>
            </YdCardContent>
          </YdCard>
        </div>
      </div>
    </div>
  </Page>
</template>
